"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[6891],{56311:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"prt/prt-introduction","title":"Permissionless Refereed Tournament - A Brief Introduction","description":"The Permissionless Refereed Tournament (PRT) is the foundational algorithm of Cartesi\u2019s fraud-proof system. It is designed so that anyone - even on a modest computer - can be a participating validator and still defeat any number of dishonest adversaries, including the resources of a nation state.","source":"@site/fraud-proofs/prt/prt-introduction.md","sourceDirName":"prt","slug":"/prt/prt-introduction","permalink":"/docs/pr-preview/pr-352/fraud-proofs/prt/prt-introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/cartesi/docs/tree/develop/fraud-proofs/prt/prt-introduction.md","tags":[],"version":"current","lastUpdatedAt":1786966359000,"frontMatter":{},"sidebar":"daveSidebar","previous":{"title":"Bonds","permalink":"/docs/pr-preview/pr-352/fraud-proofs/fraud-proof-basics/bonds"},"next":{"title":"Algorithm","permalink":"/docs/pr-preview/pr-352/fraud-proofs/prt/prt-algorithm"}}');var s=n(74848),a=n(28453);const r={},o="Permissionless Refereed Tournament - A Brief Introduction",l={},d=[{value:"Background: Traditional Fraud Proof Systems",id:"background-traditional-fraud-proof-systems",level:2},{value:"Limitations Under Sybils",id:"limitations-under-sybils",level:4},{value:"Introducing PRT Algorithm",id:"introducing-prt-algorithm",level:2}];function h(e){const t={a:"a",em:"em",h1:"h1",h2:"h2",h4:"h4",header:"header",img:"img",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"permissionless-refereed-tournament---a-brief-introduction",children:"Permissionless Refereed Tournament - A Brief Introduction"})}),"\n",(0,s.jsx)(t.p,{children:"The Permissionless Refereed Tournament (PRT) is the foundational algorithm of Cartesi\u2019s fraud-proof system. It is designed so that anyone - even on a modest computer - can be a participating validator and still defeat any number of dishonest adversaries, including the resources of a nation state."}),"\n",(0,s.jsx)(t.p,{children:"In this section, we\u2019ll look into the traditional fraud-proof models and how PRT overcomes the struggle of sybil attacks with its design elements."}),"\n",(0,s.jsx)(t.h2,{id:"background-traditional-fraud-proof-systems",children:"Background: Traditional Fraud Proof Systems"}),"\n",(0,s.jsxs)(t.p,{children:["The concept of fraud-proofs used in traditional optimistic rollups is based on the work of ",(0,s.jsx)(t.a,{href:"https://www.sciencedirect.com/science/article/pii/S0890540113000217?via%3Dihub",children:"Canetti et. al"}),". Consider the simplest setup with two players. The basic mechanism involves players agreeing on an initial state and state-transition function (STF), then running computations locally to submit final state claims to the blockchain."]}),"\n",(0,s.jsx)(t.p,{children:"If both players submit the same claim, the system accepts it. If they disagree, a verification game begins. The game proceeds in two phases. First, a bisection phase runs as a binary search over the computation, narrowing down where the players first diverge. Once the divergent step is found, the blockchain itself applies the STF once in a one-step execution, and the dishonest party is eliminated."}),"\n",(0,s.jsx)(t.p,{children:"This two-player model is simple and robust. However, when extended naively to many players, it reveals a fundamental weakness."}),"\n",(0,s.jsx)(t.h4,{id:"limitations-under-sybils",children:"Limitations Under Sybils"}),"\n",(0,s.jsx)(t.p,{children:"In the traditional model, each claim is tied to an individual player, and players cannot pool defences even if they agree. Every player must defend their claim personally, and their signatures are bound into the protocol. This allows for Sybil attacks: an adversary can spawn many identities, post the honest claim, and then deliberately lose verification games, causing the honest claim to be eliminated."}),"\n",(0,s.jsxs)(t.p,{children:["In short, its outcome reflects player elimination rather than the validation of the computational truth as called out in the EthResearch post ",(0,s.jsx)(t.a,{href:"https://ethresear.ch/t/fraud-proofs-are-broken/19234",children:"here"}),". This fragility makes the approach unsuitable for permissionless environments, where Sybils are inevitable. Early fraud proof systems, such as those used in Cartesi and Arbitrum, would suffer indefinite settlement delays, since resolution time grows linearly with the number of Sybils."]}),"\n",(0,s.jsx)(t.h2,{id:"introducing-prt-algorithm",children:"Introducing PRT Algorithm"}),"\n",(0,s.jsxs)(t.p,{children:["Permissionless Refereed Tournaments (PRT), developed by Cartesi, address this fragility by rethinking the nature of claims. Instead of committing only to the final state, PRT introduces ",(0,s.jsx)(t.em,{children:"computation hashes"})," (explained in the ",(0,s.jsx)(t.a,{href:"../../../fraud-proofs/fraud-proof-basics/state-transition-function#computation-hash",children:"Fundamental Concepts"})," section), which are stronger commitments to the entire path of the computation.\nA ",(0,s.jsx)(t.strong,{children:"computation hash"})," is built as a Merkle tree, where each leaf represents the state at every transition. In this way, a claim encodes not just an endpoint, but the full history of the computation. To defend a claim during a bisection, a player must provide a Merkle proof showing that an intermediate state is consistent with the computation hash. This eliminates the possibility of an adversary deliberately misplaying an honest claim, since the Merkle proofs themselves guarantee correctness."]}),"\n",(0,s.jsxs)(t.p,{children:["With computation hashes, the protocol shifts from ",(0,s.jsx)(t.em,{children:"revealing liars to revealing lies"}),". This shift has profound consequences. Players who agree on the same computation hash no longer need to defend claims in isolation. They can be grouped together and collaborate without requiring trust, forming what the literature calls the \u201chero\u201d side of the dispute."]}),"\n",(0,s.jsxs)(t.p,{children:["Claims are arranged in a ",(0,s.jsx)(t.strong,{children:"bracket-style tournament"}),": incompatible claims face off in matches, with half eliminated at each stage. Because each Sybil must post a bond to introduce a claim, while the hero needs only a single stake to participate, Sybil attacks become exponentially expensive for the adversary. Meanwhile, the honest hero\u2019s workload grows only logarithmically in the number of Sybils. This economic and computational asymmetry ensures that the system remains secure and decentralized."]}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.img,{alt:"PRT Tournament",src:n(46146).A+"",width:"2872",height:"1940"})}),"\n",(0,s.jsxs)(t.p,{children:["PRT also introduces refinements for scaling disputes. A fully dense computation hash, where every state transition is hashed, is often impractical for large computations. Instead, PRT begins with ",(0,s.jsx)(t.strong,{children:"sparse computation hashes"}),", where each leaf may represent many transitions."]}),"\n",(0,s.jsx)(t.p,{children:"When two sparse claims diverge, the dispute is reduced to a smaller computation, which can then be re-committed using denser computation hashes. This recursive tournament structure continues until the divergence is small enough to resolve through a standard one-step proof. The technique makes PRT feasible in practice, though it introduces additional delay: multi-stage tournaments can extend settlement time to logarithm squared in the number of Sybils."}),"\n",(0,s.jsx)(t.p,{children:"In summary, PRT enables fraud proofs that are secure where 1-of-N honesty suffices, decentralized where anyone can participate, and do not compromise of liveness where disputes settle within bounded, logarithmic time."})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(h,{...e})}):h(e)}},46146:(e,t,n)=>{n.d(t,{A:()=>i});const i=n.p+"assets/images/tournament-bracket-3544ab6450b3ecb36f81af97324305bf.png"},28453:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>o});var i=n(96540);const s={},a=i.createContext(s);function r(e){const t=i.useContext(a);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);